// ---- 4.2.20 AArch32 memory control registers ----

// MAIR attributes are preselected valures of 8 bits, in 2 registers (so 8 attributes)
// PRLAR Attribute index filed selects one of these 8 attributes

// Special 8 bits global value for device, 
pub const MAIR_ATTR_DEVICE: u32 = 0x00;
// All other values are normal memory with cacheability for
// inner and outer memory separately configured in each nibble
pub const MAIR_ATTR_NORMAL_INNER_SHIFT: usize = 0;
pub const MAIR_ATTR_NORMAL_OUTER_SHIFT: usize = 4;
// Special nibble for non cacheable
pub const MAIR_ATTR_NORMAL_NC: u32 = 0x4;
// Attributes for each outer/inner normal memory
pub const MAIR_ATTR_WRITE_ALLOC: u32 = 1 << 0;
pub const MAIR_ATTR_READ_ALLOC: u32 = 1 << 1;
pub const MAIR_ATTR_WRITE_BACK: u32 = 1 << 2;
pub const MAIR_ATTR_TRANSIENT: u32 = 1 << 3; // unused on R52

