#[inline(always)]
pub fn PAR64_get() -> u64 {
    let lo: u32;
    let hi: u32;
    unsafe {
        asm!("mrrc p15, 0, {lo}, {hi}, c7", lo = out(reg) lo, hi = out(reg) hi, options(nomem, nostack, preserves_flags));
    }
    ((hi as u64) << 32) | lo as u64
}

#[inline(always)]
pub fn PAR64_set(v: u64) {
    unsafe {
        asm!("mcrr p15, 0, {lo}, {hi}, c7", lo = in(reg) v as u32, hi = in(reg) (v >> 32) as u32, options(nostack, preserves_flags));
    }
}

